CREATE DATABASE IF NOT EXISTS CarePortal_backend;USE CarePortal_backend;CREATE TABLE Users (  user_id INT PRIMARY KEY AUTO_INCREMENT,  email VARCHAR(100) UNIQUE NOT NULL,  password_hash VARCHAR(255) NOT NULL,  role ENUM('patient', 'doctor', 'admin'),  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);CREATE TABLE Patients (  patient_id INT PRIMARY KEY AUTO_INCREMENT,  user_id INT,  first_name VARCHAR(50) NOT NULL,  last_name VARCHAR(50) NOT NULL,  date_of_birth DATE,  gender ENUM('male', 'female', 'other'),  phone VARCHAR(20),  address TEXT,  FOREIGN KEY (user_id) REFERENCES Users(user_id));CREATE TABLE Doctors (  doctor_id INT PRIMARY KEY AUTO_INCREMENT,  first_name VARCHAR(50) NOT NULL,  last_name VARCHAR(50) NOT NULL,  specialization VARCHAR(100),  email VARCHAR(100) UNIQUE,  phone VARCHAR(20));CREATE TABLE Appointments (  appointment_id INT PRIMARY KEY AUTO_INCREMENT,  patient_id INT,  doctor_id INT,  appointment_date DATETIME NOT NULL,  status ENUM('scheduled', 'completed', 'cancelled'),  notes TEXT,  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,  FOREIGN KEY (patient_id) REFERENCES Patients(patient_id),  FOREIGN KEY (doctor_id) REFERENCES Doctors(doctor_id));CREATE TABLE MedicalHistory (  history_id INT PRIMARY KEY AUTO_INCREMENT,  patient_id INT,  age        INT,  gender     ENUM('male', 'female', 'other'),  hypertension TINYINT(1),  heart_disease TINYINT(1),  smoking_history VARCHAR(50),  bmi               DECIMAL(5,2),  HbA1c_level       DECIMAL(5,2),  blood_glucose_level INT,  diagnosis_date DATE,  recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,  FOREIGN KEY (patient_id) REFERENCES Patients(patient_id));CREATE TABLE Predictions (  prediction_id INT PRIMARY KEY AUTO_INCREMENT,  patient_id INT,  symptom_id INT,  risk_level ENUM('low', 'medium', 'high'),  confidence DECIMAL(5,2),  predicted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,  FOREIGN KEY (patient_id) REFERENCES Patients(patient_id),);